export const SINDA_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/sinda-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSindaStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SINDA_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
